async function saveLinkDeployerUrl(projectId) {
  const input = document.getElementById(`deployUrl-${projectId}`);
  const url = input.value.trim();
  try { await api(`/api/projects/${projectId}/deployed-url`, { method: 'PUT', body: { url } }); showToast('Deployment link saved'); loadLinkDeployerUI(); }
  catch (e) { showToast(e.message); }
}

// ============================================================
// ARCADE — real playable memory-match game
// ============================================================
function startMemoryGame() {
  const board = document.getElementById('memoryBoard');
  if (!board) return;
  const symbols = ['♜','♞','♝','♛','♚','♟','★','◆'];
  const deck = [...symbols, ...symbols].sort(() => Math.random() - 0.5);
  let flipped = [], matched = new Set(), moves = 0;
  document.getElementById('memoryMoves').textContent = '0';
  document.getElementById('memoryMatches').textContent = '0';
  board.innerHTML = '';
  deck.forEach((sym, i) => {
    const cell = document.createElement('div');
    cell.style.cssText = 'aspect-ratio:1; background:var(--panel-bg); border:1px solid var(--panel-border); border-radius:12px; display:flex; align-items:center; justify-content:center; font-size:1.6rem; cursor:pointer; user-select:none;';
    cell.textContent = '?';
    cell.onclick = () => {
      if (flipped.length >= 2 || matched.has(i) || flipped.includes(i)) return;
      cell.textContent = sym; flipped.push(i);
      if (flipped.length === 2) {
        moves++; document.getElementById('memoryMoves').textContent = moves;
        const [a, b] = flipped; const cells = board.children;
        if (deck[a] === deck[b]) {
          matched.add(a); matched.add(b);
          document.getElementById('memoryMatches').textContent = matched.size / 2;
          flipped = [];
          if (matched.size === deck.length) showToast('You matched them all!');
        } else { setTimeout(() => { cells[a].textContent = '?'; cells[b].textContent = '?'; flipped = []; }, 700); }
      }
    };
    board.appendChild(cell);
  });
}

